// FUNCTION: BFME2 0x0033121F size=270 name=?createSelectionRadiusDecal@RadiusDecalTemplate@@QAEXUCoord3D@@IHPAVRadiusDecal@@M@Z evidence=N:ledger
void RadiusDecalTemplate::createSelectionRadiusDecal(Coord3D pos, UnsignedInt unitCount, Int color, RadiusDecal *result, Real scale)
{
	if (m_texture.isEmpty() == true || unitCount == 0 || m_minRadius == 0.0f || m_maxRadius == 0.0f)
		return;
	result->clear();
	result->m_empty = false;
	Shadow::ShadowTypeInfo info;
	info.m_texture = m_texture;
	info.m_texture2 = m_texture2;
	info.m_allowUpdates = false;
	info.m_allowWorldAlign = true;
	info.m_type = m_style;
	Real radius = getRadiusForUnitCount(unitCount);
	info.m_sizeX = radius;
	info.m_sizeY = radius;
	info.m_offsetX = 0.0f;
	info.m_offsetY = 0.0f;
	info.m_scale = scale;
	result->m_decal = TheProjectedShadowManager->addDecal(&info);
	if (result->m_decal)
	{
		result->m_decal->setAngle(0.0f);
		result->m_decal->setColor(color);
		result->m_decal->setPosition(pos);
		result->m_template = this;
	}
}


// FUNCTION: BFME2 0x0033132D size=300 name=?createDeathDecal@RadiusDecalTemplate@@QAEXPBUCoord3D@@MPBIPAVRadiusDecal@@@Z evidence=N:ledger
void RadiusDecalTemplate::createDeathDecal(const Coord3D *pos, Real angle, const UnsignedInt *color, RadiusDecal *result)
{
	if (m_texture.isEmpty() == true || pos == NULL || m_minRadius == 0.0f || m_maxRadius == 0.0f)
		return;
	result->clear();
	result->m_empty = false;
	Shadow::ShadowTypeInfo info;
	info.m_texture = m_texture;
	info.m_texture2 = m_texture2;
	info.m_sizeX = m_maxRadius;
	info.m_sizeY = m_maxRadius;
	info.m_type = m_style;
	info.m_allowUpdates = true;
	info.m_allowWorldAlign = true;
	info.m_offsetX = 0.0f;
	info.m_offsetY = 0.0f;
	result->m_decal = TheProjectedShadowManager->addDecal(&info);
	if (result->m_decal)
	{
		result->m_decal->setAngle(angle);
		result->m_decal->setColor(*color);
		Coord3D position;
		position.x = pos->x + info.m_offsetX;
		position.y = pos->y + info.m_offsetY;
		position.z = pos->z;
		result->m_decal->setPosition(position);
		result->m_template = this;
	}
}


// FUNCTION: BFME2 0x00331459 size=287 name=?createRadiusDecal@RadiusDecalTemplate@@QBEXABUCoord3D@@MPBVPlayer@@AAVRadiusDecal@@@Z evidence=N:ledger

void RadiusDecalTemplate::createRadiusDecal(const Coord3D &pos, Real radius,
    const Player *owningPlayer, RadiusDecal &result) const
{
    result.clear();
    if (!owningPlayer || m_texture.isEmpty() || radius <= 0.0f)
        return;
    result.m_empty = false;
    if (m_onlyVisibleToOwningPlayer && owningPlayer->getPlayerIndex() !=
        ThePlayerList->getLocalPlayer()->getPlayerIndex())
        return;
    Shadow::ShadowTypeInfo info;
    info.m_allowUpdates = false;
    info.m_allowWorldAlign = true;
    info.m_type = m_style;
    info.m_texture = m_texture;
    info.m_texture2 = m_texture2;
    info.m_sizeX = radius * 2.0f;
    info.m_sizeY = radius * 2.0f;
    result.m_decal = TheProjectedShadowManager->addDecal(&info);
    if (result.m_decal)
    {
        result.m_decal->setAngle(0.0f);
        result.m_decal->setColor(m_color ? m_color : owningPlayer->m_color);
        result.m_decal->setPosition(pos);
        if (radius > 110.0f)
            result.m_decal->m_largeRadius = true;
        result.m_template = this;
    }
}

// FUNCTION: BFME2 0x00331578 size=179 name=?rva00331578@RadiusDecalTemplate@@QBE_NABV1@@Z evidence=?:placeholder
Bool RadiusDecalTemplate::equals(const RadiusDecalTemplate &that) const
{
	return m_style == that.m_style
		&& m_opacityMin == that.m_opacityMin
		&& m_opacityMax == that.m_opacityMax
		&& m_opacityThrobTime == that.m_opacityThrobTime
		&& m_color == that.m_color
		&& m_texture.compare(that.m_texture) == 0
		&& m_texture2.compare(that.m_texture2) == 0
		&& m_maxRadius == that.m_maxRadius
		&& m_minRadius == that.m_minRadius
		&& m_maxSelectedUnits == that.m_maxSelectedUnits
		&& m_rotationsPerMinute == that.m_rotationsPerMinute
		&& m_spiralAcceleration == that.m_spiralAcceleration;
}
